/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    ret = ret 
        && this.validateBirthAndDeathDate();

    return ret;
}

public boolean validateBirthAndDeathDate()
{
    if (this.DeathDate > dateNull()
        && this.BirthDate > this.DeathDate)
    {
        return checkfailed("@ITFormacion:DeathDateMustBeLaterThanBirthDate");
    }

    return true;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(FTDAuthorTable, IsDead):
            this.modifiedIsDead();
            break;
        case fieldNum (FTDAuthorTable, BirthDate):
            //this.modifiedBirthDate();
            //break
    }

}

public void modifiedIsDead()
{
    if (!this.IsDead)
    {
        this.DeathDate = dateNull();
    }

    this.setDeathDateEditableInForm();
}

public void setDeathDateEditableInForm()
{
    FormDataSource formDatasource = FormDataUtil::getFormDataSource(this);

    if (formDataSource)
    {
        formDataSource.object(fieldNum(FTDAuthorTable, DeathDate)).allowEdit(this.IsDead);
    }    
}

public static FTDAuthorTable findRecId(RefRecId _refRecId, boolean _forUpdate = false)
{
    FTDAuthorTable authorTable;

    if (_refRecId)
    {
        if (_forUpdate)
        {
            authorTable.selectForUpdate(_forUpdate);
        }

        select firstonly authorTable
            where authorTable.RecId == _refRecId;
    }

    return authorTable;
}

public static FTDAuthorTable find(FTDId _id, boolean _forUpdate = false)
{
    FTDAuthorTable authorTable;

    if (_id)
    {
        if (_forUpdate)
        {
            authorTable.selectForUpdate(_forUpdate);
        }

        select firstonly authorTable
            where authorTable.Id == _id;
    }

    return authorTable;
}

